window.RP_SESSION={"id":"S-423e0fd5b5f3","messages":[{"id":"RP-0170039","time":"2026-05-31T02:19:00+09:00","room":"RP","name":"레마","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"어제 부추를 따온게 좀 남았다.","characters":["P-fec1db60d51e"]},{"id":"RP-0170040","time":"2026-05-31T02:20:00+09:00","room":"RP","name":"레마","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"부추. 이게 녹기 전에 써야 하는데...","characters":["P-fec1db60d51e"]},{"id":"RP-0170041","time":"2026-05-31T02:20:00+09:00","room":"RP","name":"레마","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"끝이 누렇게 무르면 이상한 향이 나고 맛이 없어지니까.","characters":["P-fec1db60d51e"]},{"id":"RP-0170042","time":"2026-05-31T02:21:00+09:00","room":"RP","name":"레마","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"레마는 부엌을 뒤지다가 소금에 절여 둔 생선을 찾는다.","characters":["P-fec1db60d51e"]},{"id":"RP-0170043","time":"2026-05-31T02:22:00+09:00","room":"RP","name":"멜리아 루넬리오스","profile":"멜리아 루넬리오스","identity":"reviewed","type":"dialogue","body":"\"레마, 거기서 뭐해?\"\n잠이 오지 않아 돌아다니던 멜리아.","characters":["P-5401fadc6bc3"]},{"id":"RP-0170044","time":"2026-05-31T02:22:00+09:00","room":"RP","name":"레마","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"필렛이 잡힌 형태나 살 색깔을 보아하니 잉어...","characters":["P-fec1db60d51e"]},{"id":"RP-0170045","time":"2026-05-31T02:23:00+09:00","room":"RP","name":"레마","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 멜리아! 어, 어서 와. 마침 요, 요리를 하려 했는데, 같이 먹을래? \"","characters":["P-fec1db60d51e"]},{"id":"RP-0170046","time":"2026-05-31T02:23:00+09:00","room":"RP","name":"멜리아 루넬리오스","profile":"멜리아 루넬리오스","identity":"reviewed","type":"dialogue","body":"\"좋지! 오늘도 기대할게! 헤헤...\"","characters":["P-5401fadc6bc3"]},{"id":"RP-0170047","time":"2026-05-31T02:26:00+09:00","room":"RP","name":"레마","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"일단 잉어에서 소금을 털어내고 물과 맥주를 반반 섞은 액체를 팬에 두른 뒤, 소금과 약간의 식초로 간해서 잉어 필렛을 삶기 시작한다.","characters":["P-fec1db60d51e"]},{"id":"RP-0170048","time":"2026-05-31T02:27:00+09:00","room":"RP","name":"레마","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"수분이 빠진데다 알코올과 산 덕분에 모양이 잉어 살이 뭉개지지 않고 자작하게 졸아들 때 까지 잘 익고 있다.","characters":["P-fec1db60d51e"]},{"id":"RP-0170049","time":"2026-05-31T02:29:00+09:00","room":"RP","name":"레마","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"부추를 잘 다지고 어제 쓰지 않은 한 줌 정도의 식용 풀들도 잘 다진다.","characters":["P-fec1db60d51e"]},{"id":"RP-0170050","time":"2026-05-31T02:30:00+09:00","room":"RP","name":"멜리아 루넬리오스","profile":"멜리아 루넬리오스","identity":"reviewed","type":"dialogue","body":"옆에서 구경한다.","characters":["P-5401fadc6bc3"]},{"id":"RP-0170051","time":"2026-05-31T02:30:00+09:00","room":"RP","name":"레마","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"마늘 한 쪽, 소금, 빵 조금, 식초, 가루밖에 안 남은 약간의 싸구려 허브를 꺼낸다.","characters":["P-fec1db60d51e"]},{"id":"RP-0170052","time":"2026-05-31T02:31:00+09:00","room":"RP","name":"레마","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"빵들을 식초를 섞은 물에 담가서 부드럽게 적신다.","characters":["P-fec1db60d51e"]},{"id":"RP-0170053","time":"2026-05-31T02:31:00+09:00","room":"RP","name":"레마","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"다진 부추, 몇 가지 풀들, 마늘, 허브를 절구에 넣고 빻아준다.","characters":["P-fec1db60d51e"]},{"id":"RP-0170054","time":"2026-05-31T02:31:00+09:00","room":"RP","name":"레마","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"빻빻빻빻빻...","characters":["P-fec1db60d51e"]},{"id":"RP-0170055","time":"2026-05-31T02:32:00+09:00","room":"RP","name":"레마","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"식초물을 잘 빨아들인 빵을 절구에 넣고 같이 빻는다.","characters":["P-fec1db60d51e"]},{"id":"RP-0170056","time":"2026-05-31T02:32:00+09:00","room":"RP","name":"레마","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"빻빻빻빻빻...","characters":["P-fec1db60d51e"]},{"id":"RP-0170057","time":"2026-05-31T02:32:00+09:00","room":"RP","name":"레마","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"정확히 계산된 잉어 살이 구워지는 향기가 구수하게 올라오고.","characters":["P-fec1db60d51e"]},{"id":"RP-0170058","time":"2026-05-31T02:34:00+09:00","room":"RP","name":"레마","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"잘 익은 잉어 살을 딱딱한 빵 그릇 위에 담고 절구에서 그린소스를 긁어내려서 잉어 살 위에 얹으면","characters":["P-fec1db60d51e"]},{"id":"RP-0170059","time":"2026-05-31T02:34:00+09:00","room":"RP","name":"레마","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"그린소스 잉어찜 완성!","characters":["P-fec1db60d51e"]},{"id":"RP-0170060","time":"2026-05-31T02:34:00+09:00","room":"RP","name":"레마","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 자, 멜리아! 머, 먹어 봐. \"\n\n포크를 주며.","characters":["P-fec1db60d51e"]},{"id":"RP-0170061","time":"2026-05-31T02:35:00+09:00","room":"RP","name":"멜리아 루넬리오스","profile":"멜리아 루넬리오스","identity":"reviewed","type":"dialogue","body":"\"응!\"\n눈 반짝거리며 포크 받아들고는 잉어찜 찍어서 입에 넣는다.","characters":["P-5401fadc6bc3"]},{"id":"RP-0170062","time":"2026-05-31T02:40:00+09:00","room":"RP","name":"레마","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 어, 어때? \"\n\n기대 가득한 눈으로 멜리아를 바라본다.","characters":["P-fec1db60d51e"]},{"id":"RP-0170063","time":"2026-05-31T02:52:00+09:00","room":"RP","name":"숀","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"\" 뭐야? 맛있는 냄새가 나는데. ㅎ \"","characters":["P-5c88d36f51cd"]},{"id":"RP-0170064","time":"2026-05-31T03:13:00+09:00","room":"RP","name":"레마","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 손 씨! 어, 어서 와요. 잉어를 좀 구, 구웠어요! \"","characters":["P-fec1db60d51e"]},{"id":"RP-0170065","time":"2026-05-31T03:22:00+09:00","room":"RP","name":"숀","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"\" 오~! 냄새가 기가 막히는데? 네가 잡은거야? \"","characters":["P-5c88d36f51cd"]},{"id":"RP-0170066","time":"2026-05-31T03:29:00+09:00","room":"RP","name":"레마","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 아뇨, 얼마 저, 전에 누가 잡아서 소, 소금에 절여둔거에요! 상태가 조, 좋더라구요. \"","characters":["P-fec1db60d51e"]},{"id":"RP-0170067","time":"2026-05-31T03:30:00+09:00","room":"RP","name":"숀","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"\" 그래? 나도 한 번 먹어봐도 되나?? \"","characters":["P-5c88d36f51cd"]},{"id":"RP-0170068","time":"2026-05-31T03:30:00+09:00","room":"RP","name":"레마","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 여, 여기요! \"\n\n숀에게도 포크를 주고 생선이 담긴 빵 그릇을 건낸다.","characters":["P-fec1db60d51e"]},{"id":"RP-0170069","time":"2026-05-31T03:34:00+09:00","room":"RP","name":"숀","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"\" 오. 제대로 구웠는데? 껍질도 바삭하고. 안은 또 촉촉하고. 이런 생선 요리엔 포도주도 한 잔 있으면 좋겠네. \"","characters":["P-5c88d36f51cd"]},{"id":"RP-0170070","time":"2026-05-31T03:34:00+09:00","room":"RP","name":"숀","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"\" 이건 어디서 배운거야? 아님, 직접 개발한 조리법인감? \"","characters":["P-5c88d36f51cd"]},{"id":"RP-0170071","time":"2026-05-31T03:36:00+09:00","room":"RP","name":"레마","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 마귀 할멈한테 배, 배운 레시피에요. 그 분 레시피는 어, 언제나 환상적이죠! \"","characters":["P-fec1db60d51e"]},{"id":"RP-0170072","time":"2026-05-31T03:37:00+09:00","room":"RP","name":"숀","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"\" 맛있다. 이 요리만 두고 보면, 카프리제 저리 가라 할 정도야. \"","characters":["P-5c88d36f51cd"]},{"id":"RP-0170073","time":"2026-05-31T03:38:00+09:00","room":"RP","name":"레마","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 카프리제 씨 처, 처럼 대량의 요리를 마, 맛있게 하는건 익숙지 아, 않지만요. 혼자 마, 만들어 먹거나 몇 명이서 나, 나눠 먹는 요리는 자신이 이, 있죠! \"","characters":["P-fec1db60d51e"]},{"id":"RP-0170074","time":"2026-05-31T03:39:00+09:00","room":"RP","name":"숀","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"\" 종종 느끼는거쥐만, 넌 재능이 많은 것 같어. \"","characters":["P-5c88d36f51cd"]},{"id":"RP-0170075","time":"2026-05-31T03:41:00+09:00","room":"RP","name":"레마","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 칭찬 고, 고마워요! 그래도 다 자, 잘하는건 아닌 것 가, 같아요. 마법 가, 같은건 그렇게 열심히 배, 배웠어도 잘 모, 못하구요. 앞으로 더 여, 열심히 정진해야죠! \"","characters":["P-fec1db60d51e"]},{"id":"RP-0170076","time":"2026-05-31T03:42:00+09:00","room":"RP","name":"숀","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"\" 난 요리엔 영 젬병이거든. 참을성도 없고. \"","characters":["P-5c88d36f51cd"]},{"id":"RP-0170077","time":"2026-05-31T03:46:00+09:00","room":"RP","name":"레마","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 요리도 무, 물론 중요하지만, 숀 씨는 더 자, 잘 하시는 것들이 많으니까요! \"","characters":["P-fec1db60d51e"]},{"id":"RP-0170078","time":"2026-05-31T03:47:00+09:00","room":"RP","name":"멜리아 루넬리오스","profile":"멜리아 루넬리오스","identity":"reviewed","type":"dialogue","body":"\"이거 완전 맛있다!\"\n눈 빛내며 신난 말투로 얘기한다.","characters":["P-5401fadc6bc3"]},{"id":"RP-0170079","time":"2026-05-31T03:52:00+09:00","room":"RP","name":"레마","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 웅, 멜리아도 마, 맛있게 먹어 줘서 고마워! \"","characters":["P-fec1db60d51e"]},{"id":"RP-0170080","time":"2026-05-31T21:59:00+09:00","room":"RP","name":"장면 종료 알림","profile":"델타인","identity":"reviewed","type":"dialogue","body":"-fin","characters":[]},{"id":"RP-0170081","time":"2026-05-31T21:59:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"...다음 시간에.","characters":[]}]};
